protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Create a list to hold the vertices in the tour order
    List<V> vertices = new ArrayList<>();
    // Add the source vertex of the first edge to the list
    vertices.add(tour.iterator().next().getEndpoint(graph).get(0));
    // Iterate over the edges in the tour set
    for (E edge : tour) {
        // Get the endpoint of the current edge that is not the last vertex added to the list
        V endpoint = edge.getEndpoint(graph).get(1 - vertices.indexOf(edge.getEndpoint(graph).get(0)));
        // Add the endpoint to the list
        vertices.add(endpoint);
    }
    // Create a graph path from the list of vertices
    return graph.createPath(vertices);
}

